create table if not exists public.banks(bank_id bigint generated always as identity primary key,bank_code text not null,bank_name text not null,country_id bigint not null references public.countries(country_id),unique(bank_code,country_id));
create table if not exists public.bank_account(bank_account_id bigint generated always as identity primary key,account_number text not null,bank_id bigint not null references public.banks(bank_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),account_id bigint not null references public.chart_accounts(account_id),balance numeric(24,6) not null default 0,unique(account_number,bank_id,subsidiary_id));
do $$ declare t text;begin foreach t in array array['banks','bank_account']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "banking_select" on public.%I',t);execute format('drop policy if exists "banking_insert" on public.%I',t);execute format('drop policy if exists "banking_update" on public.%I',t);execute format('drop policy if exists "banking_delete" on public.%I',t);execute format('create policy "banking_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "banking_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "banking_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "banking_delete" on public.%I for delete to authenticated using(true)',t);end loop;end $$;
